"""Model performance view - reads ONLY evaluation files generated by the scripts."""

from __future__ import annotations

import altair as alt
import pandas as pd
import streamlit as st

import config
from src.ui import empty_state, esc, load_model_config, notice, stat_tiles
from src.utils import load_json_if_exists

PALETTE = ["#0F766E", "#1E3A5F", "#64748B", "#14B8A6"]


def _fmt(v) -> str:
    return "n/a" if v is None else f"{v:.3f}"


def render_performance() -> None:
    candidates = [a for a in config.ARCHITECTURES
                  if (config.RESULTS_DIR / a / "test_metrics.json").is_file()
                  or (config.RESULTS_DIR / a / "training_history.json").is_file()]
    if not candidates:
        empty_state("chart", "No evaluation results yet",
                    "This view shows only real metrics computed on held-out test data. None exist yet, so nothing "
                    "is shown and no example numbers are substituted.",
                    commands=["python scripts/train_model.py --model densenet121 --mode development",
                              "python scripts/evaluate_model.py --model densenet121"])
        return

    arch = st.selectbox("Model", candidates, format_func=lambda a: config.ARCHITECTURES[a]["display_name"],
                        disabled=len(candidates) == 1)
    rdir = config.RESULTS_DIR / arch
    test = load_json_if_exists(rdir / "test_metrics.json")
    history = load_json_if_exists(rdir / "training_history.json")
    mcfg = load_model_config(arch)

    if mcfg.get("mode") == "development":
        sizes = " · ".join(f"{k}: {v['images']:,} images / {v['patients']:,} patients"
                           for k, v in (mcfg.get("split_sizes") or {}).items())
        notice(f"Computed on a limited development subset and not representative of full-dataset performance. "
               f"{esc(sizes)}", "warning", "Development-subset results.")

    tabs = st.tabs(["Overview", "Per finding", "Curves & matrices", "Training history", "Configuration",
                    "Model comparison"])

    with tabs[0]:
        if not test:
            empty_state("chart", "Model trained but not yet evaluated",
                        "Test-set metrics appear here after evaluation has been run.",
                        commands=[f"python scripts/evaluate_model.py --model {arch}"])
        else:
            st.caption(f"{test['num_samples']:,} held-out test images · thresholds selected on "
                       f"{test.get('thresholds_selected_on')} ({test.get('threshold_method')}) · evaluated "
                       f"{test['generated_at']}")
            stat_tiles([
                ("Macro ROC-AUC", _fmt(test["macro"]["roc_auc"]), "ranking quality, 0.5 = chance"),
                ("Macro PR-AUC", _fmt(test["macro"]["average_precision"]), "baseline = prevalence"),
                ("Macro F1", _fmt(test["macro"]["f1"]), "at review thresholds"),
                ("Micro F1", _fmt(test["micro"]["f1"]), "pooled over findings"),
            ])
            stat_tiles([
                ("Macro recall", _fmt(test["macro"]["recall"]), "sensitivity"),
                ("Macro precision", _fmt(test["macro"]["precision"]), ""),
                ("Model size", f"{test.get('model_size_mb')} MB", ""),
                ("Latency per image", f"{test['inference']['single_image_latency_ms']} ms", "CPU"),
            ])
            if test.get("labels_with_undefined_auc"):
                notice("AUC is undefined (no positives in the test split) for: "
                       + esc(", ".join(config.DISPLAY_NAMES[x] for x in test["labels_with_undefined_auc"]))
                       + ". These are excluded from macro AUC and PR-AUC.", "info")
            with st.expander("How to read these metrics"):
                st.markdown(
                    "- **Class imbalance:** most findings occur in a small percentage of images, so accuracy is "
                    "dominated by true negatives and is not used as a headline metric.\n"
                    "- **ROC-AUC** measures ranking quality independent of threshold; **PR-AUC** (average "
                    "precision) is more informative for rare findings because its baseline equals prevalence.\n"
                    "- **False negatives** (missed findings) and **false positives** (false alarms) trade off via "
                    "the threshold; thresholds here maximise F1 on the validation split, which is one possible "
                    "choice.\n"
                    "- **Macro** averages weight every finding equally; **micro** averages pool all image-finding "
                    "pairs and are dominated by common findings.")

    with tabs[1]:
        csv = rdir / "per_label_metrics.csv"
        if csv.is_file():
            per = pd.read_csv(csv)
            st.dataframe(per, width="stretch", hide_index=True)
            long = per.melt(id_vars="label", value_vars=["roc_auc", "average_precision", "f1", "recall"],
                            var_name="metric", value_name="value").dropna()
            chart = alt.Chart(long).mark_bar(cornerRadiusTopLeft=2, cornerRadiusTopRight=2).encode(
                x=alt.X("label:N", title=None, sort=None), xOffset="metric:N",
                y=alt.Y("value:Q", scale=alt.Scale(domain=[0, 1])),
                color=alt.Color("metric:N", scale=alt.Scale(range=PALETTE)),
                tooltip=["label", "metric", alt.Tooltip("value:Q", format=".3f")])
            st.altair_chart(chart.properties(height=360), width="stretch")
        else:
            st.info("Per-finding metrics are not available yet — run the evaluation script.")
        val = load_json_if_exists(rdir / "validation_metrics.json")
        if val:
            with st.expander("Validation-split metrics (used for threshold selection, not a final result)"):
                st.dataframe(pd.DataFrame({config.DISPLAY_NAMES[k]: {m: v[m] for m in ("roc_auc", "f1", "threshold")}
                                           for k, v in val["per_label"].items()}).T, width="stretch")

    with tabs[2]:
        images = [("ROC curves", rdir / "roc_curves" / "roc_all.png"),
                  ("Precision-recall curves", rdir / "precision_recall_curves" / "pr_all.png"),
                  ("Per-finding performance", rdir / "per_label_performance.png"),
                  ("Confusion matrices at review thresholds",
                   rdir / "confusion_matrices" / "confusion_matrices_all.png")]
        available = [(t, p) for t, p in images if p.is_file()]
        if not available:
            st.info("No curve or confusion-matrix figures found — run the evaluation script.")
        curves = [a for a in available if a[0] in ("ROC curves", "Precision-recall curves")]
        wide = [a for a in available if a not in curves]
        if curves:
            for col, (title, path) in zip(st.columns(len(curves), gap="medium"), curves):
                col.markdown(f"**{title}**")
                col.image(str(path), width="stretch")
        for title, path in wide:
            st.markdown(f"**{title}**")
            st.image(str(path), width="stretch")

    with tabs[3]:
        if history and history.get("history"):
            h = pd.DataFrame(history["history"])
            h["epoch"] = range(1, len(h) + 1)
            cols = st.columns(3, gap="medium")
            for col, (metric, title) in zip(cols, (("loss", "Loss"), ("auc", "Macro ROC-AUC"),
                                                   ("pr_auc", "Macro PR-AUC"))):
                series = [c for c in (metric, f"val_{metric}") if c in h]
                if not series:
                    continue
                long = h.melt(id_vars="epoch", value_vars=series, var_name="series", value_name="value")
                col.altair_chart(alt.Chart(long).mark_line(point=True).encode(
                    x="epoch:O", y=alt.Y("value:Q", title=None, scale=alt.Scale(zero=False)),
                    color=alt.Color("series:N", scale=alt.Scale(range=PALETTE[:2]),
                                    legend=alt.Legend(orient="top", title=None)),
                ).properties(title=title, height=300), width="stretch")
            stage1 = mcfg.get("stage1_epochs_completed")
            if stage1 and stage1 < len(h):
                st.caption(f"Epochs 1–{stage1}: classification head only; epochs {stage1 + 1}–{len(h)}: fine-tuning.")
        else:
            st.info("Training history is not available.")

    with tabs[4]:
        if mcfg:
            stat_tiles([
                ("Training time", f"{mcfg.get('training_seconds', 0) / 60:.1f} min", ""),
                ("Epochs completed", str(mcfg.get("epochs_completed")), ""),
                ("ImageNet initialisation", "Yes" if mcfg.get("pretrained_weights_loaded") else "No", ""),
            ])
            st.markdown(f"**Split method:** {mcfg.get('split_method')}")
            if mcfg.get("split_sizes"):
                st.dataframe(pd.DataFrame(mcfg["split_sizes"]).T, width="stretch")
            with st.expander("Training configuration"):
                st.json(mcfg.get("train_config", {}), expanded=True)
            thr = load_json_if_exists(config.MODELS_DIR / arch / "threshold_config.json")
            if thr:
                with st.expander("Review thresholds (selected on the validation split)"):
                    st.dataframe(pd.Series({config.DISPLAY_NAMES[k]: v for k, v in thr["thresholds"].items()},
                                           name="threshold"), width="stretch")
            with st.expander("Software environment"):
                st.json(mcfg.get("environment", {}))
        else:
            st.info("Model configuration is not available.")

    with tabs[5]:
        comp = config.RESULTS_DIR / "model_comparison.csv"
        if comp.is_file():
            cdf = pd.read_csv(comp)
            st.dataframe(cdf, width="stretch", hide_index=True)
            if len(cdf) > 1:
                long = cdf.melt(id_vars="model", value_vars=["macro_roc_auc", "macro_pr_auc", "macro_f1"],
                                var_name="metric", value_name="value")
                st.altair_chart(alt.Chart(long).mark_bar().encode(
                    x="metric:N", xOffset="model:N", y=alt.Y("value:Q", scale=alt.Scale(domain=[0, 1])),
                    color=alt.Color("model:N", scale=alt.Scale(range=PALETTE))), width="stretch")
                if cdf["mode"].nunique() > 1:
                    notice("Models were trained in different modes; the comparison is not like-for-like.", "warning")
            else:
                st.caption("Train and evaluate a second architecture (e.g. MobileNetV2) to compare models.")
        else:
            st.info("No evaluated models to compare yet.")
